from pathlib import Path

p = Path('app/src/main/java/com/najme/perplexityprobe/PersianKeyboardService.java')
s = p.read_text()

def replace_once(old, new, label):
    global s
    if old not in s:
        raise SystemExit(f'v1.8 patch: missing pattern: {label}')
    s = s.replace(old, new, 1)

# ---- Carry forward the validated v1.7 interaction changes ----
replace_once('import android.view.KeyEvent;\n', 'import android.view.KeyEvent;\nimport android.view.MotionEvent;\n', 'MotionEvent import')

replace_once('''    private int pendingBytes;\n    private int credentialAttempt;\n''', '''    private int pendingBytes;\n\n    private boolean backspaceHeld;\n    private boolean backspaceWordMode;\n    private final Runnable backspaceRepeater = new Runnable() {\n        @Override public void run() {\n            if (!backspaceHeld) return;\n            if (backspaceWordMode) {\n                deletePreviousWord();\n                main.postDelayed(this, 145L);\n                return;\n            }\n            InputConnection ic = getCurrentInputConnection();\n            CharSequence before = null;\n            try { if (ic != null) before = ic.getTextBeforeCursor(1, 0); } catch (Exception ignored) {}\n            if (before != null && before.length() > 0 && Character.isWhitespace(before.charAt(before.length() - 1))) {\n                backspaceWordMode = true;\n                main.postDelayed(this, 145L);\n            } else {\n                backspaceOnce();\n                main.postDelayed(this, 52L);\n            }\n        }\n    };\n\n    private int credentialAttempt;\n''', 'backspace state')

replace_once('''        bar.addView(toolbarButton("G⇄", v -> setStatus("Translate: next build")), toolbarLp(0.85f));\n        Button clip = toolbarButton("▣", v -> pasteClipboard());\n''', '''        bar.addView(toolbarButton("G⇄", v -> { stopVoiceForManualInput(); setStatus("Translate: next build"); }), toolbarLp(0.85f));\n        Button clip = toolbarButton("▣", v -> { stopVoiceForManualInput(); pasteClipboard(); });\n''', 'toolbar translate/clipboard stop')
replace_once('''        Button floating = toolbarButton("▱", v -> setStatus("Floating mode: next build"));\n''', '''        Button floating = toolbarButton("▱", v -> { stopVoiceForManualInput(); setStatus("Floating mode: next build"); });\n''', 'toolbar floating stop')

s = s.replace('actionKey("⌫", v -> backspace())', 'backspaceKey()')
if 'v -> backspace()' in s:
    raise SystemExit('v1.8 patch: old backspace action remains')

replace_once('''    private Button charKey(String label) {\n        Button b=baseKey(label,false); b.setOnClickListener(v -> commitText(label));\n        String[] vars=longPress.get(label); if (vars!=null) b.setOnLongClickListener(v -> { showVariants(b,vars); return true; });\n        return b;\n    }\n\n    private Button actionKey(String label, View.OnClickListener listener) { Button b=baseKey(label,true); b.setOnClickListener(listener); return b; }\n''', '''    private Button charKey(String label) {\n        Button b=baseKey(label,false);\n        b.setOnClickListener(v -> { stopVoiceForManualInput(); commitText(label); });\n        String[] vars=longPress.get(label);\n        if (vars!=null) b.setOnLongClickListener(v -> { stopVoiceForManualInput(); showVariants(b,vars); return true; });\n        return b;\n    }\n\n    private Button actionKey(String label, View.OnClickListener listener) {\n        Button b=baseKey(label,true);\n        b.setOnClickListener(v -> { stopVoiceForManualInput(); listener.onClick(v); });\n        return b;\n    }\n\n    private Button backspaceKey() {\n        Button b=baseKey("⌫",true);\n        b.setOnTouchListener((v,event) -> {\n            int action=event.getActionMasked();\n            if(action==MotionEvent.ACTION_DOWN){\n                stopVoiceForManualInput();\n                backspaceHeld=true; backspaceWordMode=false;\n                backspaceOnce();\n                main.removeCallbacks(backspaceRepeater);\n                main.postDelayed(backspaceRepeater,330L);\n                return true;\n            }\n            if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){\n                backspaceHeld=false;\n                main.removeCallbacks(backspaceRepeater);\n                return true;\n            }\n            return true;\n        });\n        return b;\n    }\n''', 'key wrappers')

replace_once('''    private String alphaLabel(){return persian?"ابپ":"ABC";}\n    private void toggleLanguage(){\n        if(running){setStatus("Stop voice before changing language");return;}\n        persian=!persian; shift=false; layer=Layer.ALPHA; getSharedPreferences("keyboard",MODE_PRIVATE).edit().putBoolean("persian",persian).apply(); render(); setStatus(readyText());\n    }\n''', '''    private String alphaLabel(){return persian?"ابپ":"ABC";}\n    private void toggleLanguage(){\n        stopVoiceForManualInput();\n        persian=!persian; shift=false; layer=Layer.ALPHA; getSharedPreferences("keyboard",MODE_PRIVATE).edit().putBoolean("persian",persian).apply(); render(); setStatus(readyText());\n    }\n''', 'language switch')

replace_once('''    private void backspace(){\n        InputConnection ic=getCurrentInputConnection(); if(ic==null)return; try{CharSequence sel=ic.getSelectedText(0); if(sel!=null&&sel.length()>0)ic.commitText("",1); else ic.deleteSurroundingText(1,0);}catch(Exception ignored){}\n    }\n''', '''    private void backspaceOnce(){\n        InputConnection ic=getCurrentInputConnection(); if(ic==null)return;\n        try{CharSequence sel=ic.getSelectedText(0); if(sel!=null&&sel.length()>0)ic.commitText("",1); else ic.deleteSurroundingText(1,0);}catch(Exception ignored){}\n    }\n\n    private void deletePreviousWord(){\n        InputConnection ic=getCurrentInputConnection(); if(ic==null)return;\n        try{\n            CharSequence sel=ic.getSelectedText(0);\n            if(sel!=null&&sel.length()>0){ic.commitText("",1);return;}\n            CharSequence seq=ic.getTextBeforeCursor(256,0);\n            if(seq==null||seq.length()==0)return;\n            String before=seq.toString();\n            int end=before.length();\n            while(end>0&&Character.isWhitespace(before.charAt(end-1)))end--;\n            int start=end;\n            while(start>0&&!Character.isWhitespace(before.charAt(start-1)))start--;\n            int count=before.length()-start;\n            if(count<=0)count=1;\n            ic.deleteSurroundingText(count,0);\n        }catch(Exception ignored){}\n    }\n''', 'backspace implementation')

replace_once('''    private void switchToGboard(){\n        if(running)abortForEditorChange(); InputMethodManager imm=(InputMethodManager)getSystemService(INPUT_METHOD_SERVICE); String id=null;\n''', '''    private void stopVoiceForManualInput(){\n        if(!running)return;\n        running=false; completed=true; stopRequested=true; awaitingCredential=false; retryAfterPageLoad=false;\n        backspaceHeld=false; main.removeCallbacks(backspaceRepeater);\n        stopAudioRecord(); clearPending();\n        WebSocket ws=webSocket; webSocket=null; if(ws!=null)ws.cancel();\n        InputConnection old=boundConnection; boundConnection=null;\n        if(old!=null)try{old.finishComposingText();}catch(Exception ignored){}\n        synchronized(expectedSelectionUpdates){expectedSelectionUpdates.clear();}\n        hasComposingTail=false;\n        setCollapsed(false); updateMicUi(); setStatus(readyText());\n    }\n\n    private void switchToGboard(){\n        stopVoiceForManualInput(); InputMethodManager imm=(InputMethodManager)getSystemService(INPUT_METHOD_SERVICE); String id=null;\n''', 'manual voice interruption')

replace_once('''    @Override public void onDestroy(){running=false;stopRequested=true;stopAudioRecord();clearPending();if(webSocket!=null)webSocket.cancel();if(auth!=null){auth.removeJavascriptInterface("AndroidKeyboard");auth.destroy();}http.dispatcher().executorService().shutdown();super.onDestroy();}\n''', '''    @Override public void onDestroy(){running=false;stopRequested=true;backspaceHeld=false;main.removeCallbacks(backspaceRepeater);stopAudioRecord();clearPending();if(webSocket!=null)webSocket.cancel();if(auth!=null){auth.removeJavascriptInterface("AndroidKeyboard");auth.destroy();}http.dispatcher().executorService().shutdown();super.onDestroy();}\n''', 'onDestroy cleanup')

