replace_once('''    private String partialTranscript = "";\n    private int pendingBytes;\n''', '''    private String partialTranscript = "";\n    private int committedFinalChars;\n    private boolean hasComposingTail;\n    private int pendingBytes;\n''', 'stable transcript fields')

replace_once('''    @Override public void onFinishInput() {\n        inputGeneration++;\n        if (running) abortForEditorChange();\n        editorInfo = null;\n        super.onFinishInput();\n    }\n\n    private void render() {\n''', '''    @Override public void onFinishInput() {\n        inputGeneration++;\n        if (running) abortForEditorChange();\n        editorInfo = null;\n        super.onFinishInput();\n    }\n\n    @Override public void onUpdateSelection(int oldSelStart, int oldSelEnd, int newSelStart, int newSelEnd, int candidatesStart, int candidatesEnd) {\n        super.onUpdateSelection(oldSelStart, oldSelEnd, newSelStart, newSelEnd, candidatesStart, candidatesEnd);\n        if(!running)return;\n        if(oldSelStart==newSelStart&&oldSelEnd==newSelEnd)return;\n        if(consumeExpectedSelection(newSelStart,newSelEnd))return;\n        boolean withinComposing=candidatesStart>=0&&candidatesEnd>=candidatesStart\n                &&newSelStart>=candidatesStart&&newSelStart<=candidatesEnd\n                &&newSelEnd>=candidatesStart&&newSelEnd<=candidatesEnd;\n        if(withinComposing)return;\n        stopVoiceForManualInput();\n    }\n\n    private long selectionKey(int start,int end){return(((long)start)<<32)^(end&0xffffffffL);}\n    private void rememberProgrammaticSelection(){\n        InputConnection ic=boundConnection;if(ic==null)return;\n        try{\n            android.view.inputmethod.ExtractedTextRequest req=new android.view.inputmethod.ExtractedTextRequest();\n            android.view.inputmethod.ExtractedText et=ic.getExtractedText(req,0);\n            if(et==null)return;\n            long key=selectionKey(et.selectionStart,et.selectionEnd);\n            synchronized(expectedSelectionUpdates){\n                while(expectedSelectionUpdates.size()>=10)expectedSelectionUpdates.removeFirst();\n                expectedSelectionUpdates.addLast(key);\n            }\n        }catch(Exception ignored){}\n    }\n    private boolean consumeExpectedSelection(int start,int end){\n        long key=selectionKey(start,end);\n        synchronized(expectedSelectionUpdates){return expectedSelectionUpdates.removeFirstOccurrence(key);}\n    }\n\n    private void render() {\n''', 'outside keyboard caret cancellation')

replace_once('''        synchronized(textLock){finalTranscript.setLength(0);finalTokenIds.clear();partialTranscript="";}\n        resetAudio(); running=true; stopRequested=false; completed=false; awaitingCredential=true; credentialAttempt=0; retryAfterPageLoad=false; lastCredentialError=""; updateMicUi();\n''', '''        synchronized(textLock){finalTranscript.setLength(0);finalTokenIds.clear();partialTranscript="";committedFinalChars=0;hasComposingTail=false;}\n        synchronized(expectedSelectionUpdates){expectedSelectionUpdates.clear();}\n        resetAudio(); running=true; stopRequested=false; completed=false; awaitingCredential=true; credentialAttempt=0; retryAfterPageLoad=false; lastCredentialError=""; updateMicUi();\n''', 'reset stable transcript state')

