replace_once('''                if(audioRecord.getState()!=AudioRecord.STATE_INITIALIZED)throw new IllegalStateException("AudioRecord not initialized");audioRecord.startRecording();byte[] buf=new byte[AUDIO_CHUNK];long deadline=System.currentTimeMillis()+MAX_CAPTURE_MS;\n                while(running&&!stopRequested&&System.currentTimeMillis()<deadline){int n;try{n=audioRecord.read(buf,0,buf.length);}catch(Exception e){if(stopRequested||!running)break;throw e;}if(n>0){byte[] chunk=Arrays.copyOf(buf,n);if(!bufferOrSend(chunk))throw new IllegalStateException("Audio send rejected");}else if(n<0&&!stopRequested)throw new IllegalStateException("Audio read failed");}\n                if(running&&!stopRequested&&System.currentTimeMillis()>=deadline){stopRequested=true;main.post(()->setStatus(persian?"در حال نهایی‌سازی…":"Finalizing…"));}\n                stopAudioRecord();synchronized(audioLock){audioDone=true;}if(running&&!completed)maybeFinish();\n''', '''                if(audioRecord.getState()!=AudioRecord.STATE_INITIALIZED)throw new IllegalStateException("AudioRecord not initialized");audioRecord.startRecording();byte[] buf=new byte[AUDIO_CHUNK];\n                while(running&&!stopRequested){int n;try{n=audioRecord.read(buf,0,buf.length);}catch(Exception e){if(stopRequested||!running)break;throw e;}if(n>0){byte[] chunk=Arrays.copyOf(buf,n);if(!bufferOrSend(chunk))throw new IllegalStateException("Audio send rejected");}else if(n<0&&!stopRequested)throw new IllegalStateException("Audio read failed");}\n                stopAudioRecord();synchronized(audioLock){audioDone=true;}if(running&&!completed)maybeFinish();\n''', 'remove timed audio stop')

replace_once('''    private void publish(boolean finish){\n        final String display;synchronized(textLock){display=finalTranscript.toString()+(finish?"":partialTranscript);}main.post(()->{if(!sessionStillBound()&&!finish)return;if(boundConnection==null||activeGeneration!=inputGeneration||getCurrentInputConnection()!=boundConnection){if(running)abortForEditorChange();return;}try{boundConnection.setComposingText(display,1);if(finish)boundConnection.finishComposingText();}catch(Exception e){abortForEditorChange();}});\n    }\n''', '''    private void publish(boolean finish){\n        main.post(()->{\n            if(!sessionStillBound()&&!finish)return;\n            if(boundConnection==null||activeGeneration!=inputGeneration||getCurrentInputConnection()!=boundConnection){if(running)abortForEditorChange();return;}\n            String newFinal;String partial;int targetFinalChars;\n            synchronized(textLock){\n                String allFinal=finalTranscript.toString();\n                int from=Math.min(committedFinalChars,allFinal.length());\n                newFinal=allFinal.substring(from);\n                partial=partialTranscript;\n                targetFinalChars=allFinal.length();\n            }\n            try{\n                if(!newFinal.isEmpty()){\n                    boundConnection.commitText(newFinal,1);\n                    rememberProgrammaticSelection();\n                    synchronized(textLock){if(committedFinalChars<targetFinalChars)committedFinalChars=targetFinalChars;}\n                    hasComposingTail=false;\n                }\n                if(!partial.isEmpty()){\n                    boundConnection.setComposingText(partial,1);\n                    hasComposingTail=true;\n                    rememberProgrammaticSelection();\n                }else if(hasComposingTail){\n                    boundConnection.setComposingText("",1);\n                    hasComposingTail=false;\n                    rememberProgrammaticSelection();\n                }\n                if(finish){\n                    boundConnection.finishComposingText();\n                    hasComposingTail=false;\n                    rememberProgrammaticSelection();\n                }\n            }catch(Exception e){abortForEditorChange();}\n        });\n    }\n''', 'commit final text incrementally')

replace_once('''    private void abortForEditorChange(){\n        InputConnection old=boundConnection;running=false;stopRequested=true;awaitingCredential=false;stopAudioRecord();clearPending();WebSocket ws=webSocket;webSocket=null;if(ws!=null)ws.cancel();if(old!=null)try{old.finishComposingText();}catch(Exception ignored){} boundConnection=null;\n        main.post(()->{setCollapsed(false);updateMicUi();setStatus("Voice cancelled — editor changed");});\n    }\n''', '''    private void abortForEditorChange(){\n        InputConnection old=boundConnection;running=false;stopRequested=true;awaitingCredential=false;stopAudioRecord();clearPending();WebSocket ws=webSocket;webSocket=null;if(ws!=null)ws.cancel();if(old!=null)try{old.finishComposingText();}catch(Exception ignored){} boundConnection=null;\n        hasComposingTail=false;synchronized(expectedSelectionUpdates){expectedSelectionUpdates.clear();}\n        main.post(()->{setCollapsed(false);updateMicUi();setStatus("Voice cancelled — editor changed");});\n    }\n''', 'editor abort stable cleanup')

